import{_ as e,o,c as r,ag as t}from"./chunks/framework.B3amng90.js";const s="/abu-aigc-guide/screenshots/drama-upload.webp",i="/abu-aigc-guide/screenshots/drama-paste.webp",_=JSON.parse('{"title":"从剧本制作短剧","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/drama.md","filePath":"workflows/drama.md"}'),l={name:"workflows/drama.md"};function n(d,a,c,p,m,h){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="从剧本制作短剧" tabindex="-1">从剧本制作短剧 <a class="header-anchor" href="#从剧本制作短剧" aria-label="Permalink to &quot;从剧本制作短剧&quot;">​</a></h1><p>短剧工作室把原稿整理成故事和镜头，再逐步生成视频。进入侧栏 <strong>短剧</strong>，可以导入现有文本，也可以直接从创意开始。</p><h2 id="导入小说或剧本" tabindex="-1">导入小说或剧本 <a class="header-anchor" href="#导入小说或剧本" aria-label="Permalink to &quot;导入小说或剧本&quot;">​</a></h2><ol><li>选择 <strong>上传剧本 / 小说</strong>，拖入文件或点击 <strong>选择文件</strong>。支持 <code>txt</code>、<code>md</code>、<code>docx</code>，单份内容不超过页面提示的长度。</li><li>如果已经复制好原稿，可切换到 <strong>粘贴正文</strong>。只有故事点子时，选择 <strong>剧本创作</strong>。</li><li>填好后点击输入区右下角的 <strong>开始</strong>。进入项目后，检查故事梗概、人物关系和分集结构，再继续编写或修改分集剧本。</li></ol><p><a href="/abu-aigc-guide/screenshots/drama-upload.webp"><img src="'+s+'" alt="短剧上传标签中的选择文件按钮与文件格式提示" loading="lazy"></a></p><p><em>上传现成的剧本或小说。点击截图可查看大图。</em></p><p><a href="/abu-aigc-guide/screenshots/drama-paste.webp"><img src="'+i+'" alt="短剧切换到粘贴正文后出现的文本区和右下角的开始按钮" loading="lazy"></a></p><p><em>原稿已经复制好时，切换到「粘贴正文」。</em></p><h2 id="整理角色和场景" tabindex="-1">整理角色和场景 <a class="header-anchor" href="#整理角色和场景" aria-label="Permalink to &quot;整理角色和场景&quot;">​</a></h2><p>进入项目的资产区域，检查 AI 提取的角色、场景和道具。补充外观描述或参考图，让不同镜头中的人物与环境更一致。涉及真实人物或受版权保护的素材时，先确认授权。</p><h2 id="生成分镜" tabindex="-1">生成分镜 <a class="header-anchor" href="#生成分镜" aria-label="Permalink to &quot;生成分镜&quot;">​</a></h2><ol><li>打开要制作的分集，检查分镜顺序、画面描述、人物和场景。</li><li>选择可用的视频模型，检查镜头时长与画面比例。</li><li>先试生成少量镜头，确认人物外观、画面风格和运动效果。</li><li>按镜头查看结果；需要调整时修改对应描述并重新生成。</li><li>逐镜确认后再制作剩余镜头，并检查整集的连续性。</li></ol><p>生成能力会随当前服务开放情况变化。如果模型选项不可用或操作按钮被禁用，请联系服务支持。</p>',13)])])}const u=e(l,[["render",n]]);export{_ as __pageData,u as default};
